export interface ParsedCompletionArgs {
  /** All remaining shell tokens after stripping the runtime, binary and script name. */
  tokens: string[];
  /** The last token — the partial string currently being completed. */
  current: string;
  /** The second-to-last token, or '' when only one token is present. */
  previousToken: string;
}

/**
 * Parses a `process.argv`-style array for shell completion.
 *
 * Strips the first two entries (the node runtime and the nx binary path),
 * then strips a leading `nx` script-name token if present, and returns the
 * remaining shell tokens together with the token currently being completed
 * and the token immediately before it.
 *
 * Returns `null` when no user-supplied tokens remain after stripping.
 */
export function parseCompletionArgs(
  argv: string[]
): ParsedCompletionArgs | null {
  // The first two entries are always the node runtime and the nx binary path.
  let tokens = argv.slice(2);

  // A leading `nx` token can still be present (e.g. when the completion
  // wrapper forwards the full command line including the script name).
  if (tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
