/**
 * Reads the cached project graph, returning `null` instead of throwing when no
 * cached graph is available (which is the common case during completion where
 * we must never crash the shell).
 */
function safeReadProjectGraph(): ProjectGraph | null {
  try {
    return readCachedProjectGraph();
  } catch {
    return null;
  }
}

/**
 * Returns all project names from the cached project graph that start with the
 * given prefix. Returns [] if the project graph is unavailable.
 */
export function getProjectNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => name.startsWith(prefix));
}

/**
 * Returns project names that start with the given prefix AND have a target
 * matching the given target name. Returns [] if no projects match or the graph
 * is unavailable.
 */
export function getProjectNamesWithTarget(
  prefix: string,
  target: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter(
    (name) =>
      name.startsWith(prefix) && !!graph.nodes[name].data.targets?.[target]
  );
}

/**
 * Returns unique target names across all workspace projects that start with
 * the given prefix. Returns [] if the graph is unavailable.
 */
export function getTargetNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const targets = new Set<string>();
  for (const node of Object.values(graph.nodes)) {
    for (const target of Object.keys(node.data.targets ?? {})) {
      if (target.startsWith(prefix)) {
        targets.add(target);
      }
    }
  }
  return [...targets];
}

/**
 * Returns target names for a specific project that start with the given prefix.
 * If the project name does not exist in the graph, falls back to all workspace
 * target names (to support partial project-name typing scenarios like
 * `project:t<TAB>`).
 */
export function getTargetNamesForProject(
  prefix: string,
  projectName: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const node = graph.nodes[projectName];
  if (!node) {
    return getTargetNameCompletions(prefix);
  }
  return Object.keys(node.data.targets ?? {}).filter((target) =>
    target.startsWith(prefix)
  );
}

/**
 * Two-stage completion for `project:target` tokens.
 *
 * Stage 1 (no colon in `current`): returns matching project names each
 * suffixed with `:`.
 * Stage 2 (colon present in `current`): returns `projectName:targetName`
 * candidates matching the portion after the colon, using all workspace targets
 * when the project name is unknown.
 */
export function completeProjectTarget(current: string): string[] {
  const colonIndex = current.indexOf(':');
  if (colonIndex === -1) {
    return getProjectNameCompletions(current).map((name) => `${name}:`);
  }

  const projectName = current.slice(0, colonIndex);
  const targetPrefix = current.slice(colonIndex + 1);
  return getTargetNamesForProject(targetPrefix, projectName).map(
    (target) => `${projectName}:${target}`
  );
