 */
export type CompleteFn = (current: string, args: string[]) => string[];

export interface PositionalCompletion {
  /** Static list of candidate values, filtered by prefix. */
  choices?: string[];
  /** Dynamic completion function. Takes precedence over `choices`. */
  complete?: CompleteFn;
}

export interface CompletionMetadata {
  /** Ordered positional argument completions. */
  positionals?: PositionalCompletion[];
  /** Flag-value completions, keyed by the flag name (including dashes). */
  flags?: Record<string, CompleteFn>;
}

const registry = new Map<string, CompletionMetadata>();

/**
 * Registers completion metadata for a command path. The path is a
 * space-separated string of command tokens (e.g. `show target`).
 */
export function registerCompletion(
  path: string,
  metadata: CompletionMetadata
