  registry.set(path, metadata);
}

/**
 * Clears all registered completion metadata. Intended for use in tests.
 */
export function clearCompletionRegistry(): void {
  registry.clear();
}

function isFlag(token: string): boolean {
  return token.startsWith('--');
}

/**
 * Searches the registry for the longest registered path that matches a prefix
 * of the given tokens array. Flags (tokens starting with `--`) halt the prefix
 * walk. Returns the matching metadata and the `positionalIndex` (count of
 * non-flag tokens typed beyond the matched path, excluding the token currently
 * being completed). Returns `null` when no path matches.
 */
export function findCompletionMetadata(
  tokens: string[]
