    if (isFlag(token)) {
      break;
    }
    pathTokens.push(token);
  }

  for (let length = pathTokens.length; length >= 1; length--) {
    const key = pathTokens.slice(0, length).join(' ');
    const metadata = registry.get(key);
    if (metadata) {
      return { metadata, positionalIndex: pathTokens.length - length };
    }
