/**
 * Runs a yargs builder function in a "dry-run" mode against a recording proxy
 * and extracts the option alias groups it declares.
 *
 * Returns an object whose `aliases` Map maps each canonical option name to the
 * array of yargs-declared aliases for that option. Returns `null` on failure.
 */
export function introspectBuilder(
  builder: (yargs: Argv) => Argv
): { aliases: Map<string, string[]> } | null {
  if (typeof builder !== 'function') {
    return null;
  }

  try {
    const aliases = new Map<string, string[]>();

    const record = (key: unknown, config: unknown) => {
      if (typeof key !== 'string') {
        return;
      }
      const alias = (config as { alias?: string | string[] } | undefined)
        ?.alias;
      if (alias !== undefined) {
        aliases.set(key, Array.isArray(alias) ? [...alias] : [alias]);
      } else if (!aliases.has(key)) {
        aliases.set(key, []);
      }
    };

    let proxy: any;
    const handler: ProxyHandler<() => void> = {
      get(_target, prop) {
        if (prop === 'option' || prop === 'positional') {
          return (key: unknown, config: unknown) => {
            record(key, config);
            return proxy;
          };
        }
        if (prop === 'options') {
          return (keyOrMap: unknown, config: unknown) => {
            if (typeof keyOrMap === 'string') {
              record(keyOrMap, config);
            } else if (keyOrMap && typeof keyOrMap === 'object') {
              for (const [key, cfg] of Object.entries(keyOrMap)) {
                record(key, cfg);
              }
            }
            return proxy;
          };
        }
        // Every other yargs method is chainable; return the proxy so the
        // builder can keep chaining calls without side effects.
        return () => proxy;
      },
      apply() {
        return proxy;
      },
    };

    proxy = new Proxy(function () {}, handler);
    builder(proxy as unknown as Argv);

    return { aliases };
  } catch {
    return null;
  }
}
