  getTargetNameCompletions,
} from './completion-providers';
import { CompleteFn, CompletionMetadata, registerCompletion } from './metadata';

const projectNameCompleter: CompleteFn = (current) =>
  getProjectNameCompletions(current);
const targetNameCompleter: CompleteFn = (current) =>
  getTargetNameCompletions(current);

/**
 * Converts a yargs option name into its command-line form. Single-character
 * options use a single dash; longer names use a double dash.
 */
function dashify(name: string): string {
  return name.length === 1 ? `-${name}` : `--${name}`;
}

/**
 * Known aliases for the options we register completions for. These are merged
 * with the aliases discovered by introspecting the yargs builders so that all
 * declared aliases share a single handler reference even if a command does not
 * itself declare the option.
 */
const FALLBACK_ALIASES: Record<string, string[]> = {
  projects: ['p'],
  targets: ['target', 't'],
  target: ['targets', 't'],
  exclude: [],
  focus: [],
};

/**
 * Builds a flag-completion map for a command, keying each option (and all of
 * its aliases) to the same handler reference.
 */
function buildFlagCompletions(
  command: string,
  optionHandlers: Record<string, CompleteFn>
): Record<string, CompleteFn> {
  const handlers = getNxCommandHandlers();
  const builder = handlers[command]?.builder;
  const introspected = builder ? introspectBuilder(builder) : null;

  const flags: Record<string, CompleteFn> = {};
  for (const [canonical, handler] of Object.entries(optionHandlers)) {
    const names = new Set<string>([canonical]);
    for (const alias of introspected?.aliases.get(canonical) ?? []) {
      names.add(alias);
    }
    for (const alias of FALLBACK_ALIASES[canonical] ?? []) {
      names.add(alias);
    }
    for (const name of names) {
      flags[dashify(name)] = handler;
    }
  }
  return flags;
}

/**
 * Returns `@nx/*` package names from the nx package group whose names start
 * with the given prefix. Used to complete `nx add <package>`.
 */
function getAddPackageCompletions(prefix: string): string[] {
  let nxPackageJson: any;
  try {
    // package.json lives at the root of the nx package, three levels up from
    // this module (command-line/completion -> command-line -> src -> nx).
    nxPackageJson = readJsonFile(join(__dirname, '../../../package.json'));
  } catch {
    return [];
  }

  const packageGroup: Array<string | { package?: string }> =
    nxPackageJson?.['nx-migrations']?.packageGroup ?? [];

  return packageGroup
    .map((entry) => (typeof entry === 'string' ? entry : entry?.package))
    .filter((name): name is string => !!name)
    .filter((name) => name.startsWith('@nx/') && name.startsWith(prefix));
}

// --- Command positional completions -----------------------------------------

registerCompletion('run', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});

// `generate` and its `g` alias share the same metadata object.
const generateMetadata: CompletionMetadata = {
  positionals: [{ complete: (current) => completeGenerator(current) }],
};
registerCompletion('generate', generateMetadata);
registerCompletion('g', generateMetadata);

registerCompletion('show project', {
  positionals: [{ complete: (current) => getProjectNameCompletions(current) }],
});

registerCompletion('show target', {
  positionals: [
    {
      complete: (current) => [
        ...completeProjectTarget(current),
        ...['inputs', 'outputs'].filter((choice) => choice.startsWith(current)),
      ],
    },
  ],
});

registerCompletion('show target inputs', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});
registerCompletion('show target outputs', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});

registerCompletion('add', {
  positionals: [{ complete: (current) => getAddPackageCompletions(current) }],
});

// --- Flag-value completions --------------------------------------------------

registerCompletion('run-many', {
  flags: buildFlagCompletions('run-many', {
    projects: projectNameCompleter,
    targets: targetNameCompleter,
  }),
});

registerCompletion('affected', {
  flags: buildFlagCompletions('affected', {
    projects: projectNameCompleter,
    exclude: projectNameCompleter,
    targets: targetNameCompleter,
  }),
});

registerCompletion('graph', {
  flags: buildFlagCompletions('graph', {
    focus: projectNameCompleter,
    exclude: projectNameCompleter,
    targets: targetNameCompleter,
  }),
});

registerCompletion('watch', {
  flags: buildFlagCompletions('watch', {
    projects: projectNameCompleter,
  }),
});

// --- Infix target completions ------------------------------------------------

// `nx <target> <TAB>` should complete project names that declare that target.
const CONVENTIONAL_TARGETS = ['build', 'test', 'lint', 'serve', 'e2e', 'start'];
for (const target of CONVENTIONAL_TARGETS) {
  registerCompletion(target, {
    positionals: [
      { complete: (current) => getProjectNamesWithTarget(current, target) },
    ],
  });
}
